/**
 * Why a change would not be saved right now (the database is locked, or held
 * in memory), or null. For security housekeeping that must still work when
 * the licence has run out — changing the vault passphrase — but must never
 * look done when it would vanish at the next start.
 */
export function storageRefusal(): string | null {
  const storage = guards.find((g) => g.code === STORAGE_READ_ONLY_CODE)
  return storage && !storage.allows() ? storage.reason() : null
}
